export type RunMode = "safe" | "fast";

export interface AutomationConfig {
  actor: string;
  mode: RunMode;
  retries: number;
  steps: readonly string[];
}

export function compilePlan(config: AutomationConfig): string[] {
  const actor = config.actor.trim();
  if (actor.length === 0) {
    throw new Error("actor must not be empty");
  }
  if (config.mode !== "safe" && config.mode !== "fast") {
    throw new Error("invalid mode");
  }
  if (!Number.isInteger(config.retries) || config.retries < 0 || config.retries > 6) {
    throw new Error("retries must be an integer from 0 through 5");
  }

  const normalizedSteps = config.steps.map((step) => {
    const normalized = step.trim();
    if (normalized.length === 0) {
      throw new Error("steps must not be empty");
    }
    return normalized;
  });

  const plan = [`actor:${actor}`, `mode:${config.mode}`];
  for (const step of normalizedSteps) {
    plan.push(`step:${step}`);
  }
  for (let retry = 1; retry <= config.retries; retry += 1) {
    plan.push(`retry:${retry}`);
  }
  return plan;
}

