import { compilePlan, AutomationConfig } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function assertArray(actual: string[], expected: string[], message: string): void {
  const a = JSON.stringify(actual);
  const e = JSON.stringify(expected);
  if (a !== e) throw new Error(`${message}: expected ${e}, got ${a}`);
}

function assertThrows(action: () => unknown, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof Error, `${message}: expected Error`);
}

const steps = ['  fetch  ', '\tbuild\n', 'publish'];
const config: AutomationConfig = { actor: '  Forge  ', mode: 'safe', retries: 3, steps };
assertArray(compilePlan(config), [
  'actor:Forge',
  'mode:safe',
  'step:fetch',
  'step:build',
  'step:publish',
  'retry:1',
  'retry:2',
  'retry:3'
], 'compiles normalized plan in deterministic order');
assert(config.actor === '  Forge  ', 'actor is not mutated');
assertArray(steps, ['  fetch  ', '\tbuild\n', 'publish'], 'steps are not mutated');

assertArray(compilePlan({ actor: 'A', mode: 'fast', retries: 0, steps: [] }), [
  'actor:A',
  'mode:fast'
], 'empty steps and zero retries');
assertArray(compilePlan({ actor: 'A', mode: 'safe', retries: 5, steps: ['x'] }), [
  'actor:A', 'mode:safe', 'step:x', 'retry:1', 'retry:2', 'retry:3', 'retry:4', 'retry:5'
], 'maximum retry boundary');

const first = compilePlan(config);
const second = compilePlan(config);
assert(first !== second, 'returns a new array');
first[0] = 'corrupt';
first.push('extra');
assertArray(compilePlan(config), [
  'actor:Forge', 'mode:safe', 'step:fetch', 'step:build', 'step:publish', 'retry:1', 'retry:2', 'retry:3'
], 'returned array mutation is isolated');

const badConfigs: unknown[] = [
  { actor: '', mode: 'safe', retries: 0, steps: [] },
  { actor: '   ', mode: 'safe', retries: 0, steps: [] },
  { actor: 7, mode: 'safe', retries: 0, steps: [] },
  { actor: 'A', mode: 'SAFE', retries: 0, steps: [] },
  { actor: 'A', mode: 'slow', retries: 0, steps: [] },
  { actor: 'A', mode: 'safe', retries: -1, steps: [] },
  { actor: 'A', mode: 'safe', retries: 6, steps: [] },
  { actor: 'A', mode: 'safe', retries: 1.5, steps: [] },
  { actor: 'A', mode: 'safe', retries: Number.NaN, steps: [] },
  { actor: 'A', mode: 'safe', retries: 0, steps: [''] },
  { actor: 'A', mode: 'safe', retries: 0, steps: ['  '] },
  { actor: 'A', mode: 'safe', retries: 0, steps: [3] },
  { actor: 'A', mode: 'safe', retries: 0, steps: null }
];
for (let index = 0; index < badConfigs.length; index += 1) {
  assertThrows(() => compilePlan(badConfigs[index] as AutomationConfig), `rejects malformed config ${index}`);
}

